29	describe("claim-office CLI", () => {
30	  it(
31	    "reads a scenario from stdin and writes {results: [...]} to stdout",
32	    async () => {
33	      const { stdout, code } = await runCli(
34	        JSON.stringify({
35	          customer: { yearsWithMHPCO: 0 },
36	          steps: [{ op: "quote", items: [{ type: "sword" }] }],
37	        }),
38	      );
39	
40	      expect(code).toBe(0);
41	      expect(JSON.parse(stdout)).toEqual({ results: [{ premium: 115 }] });
42	    },
43	    CLI_TIMEOUT_MS,
44	  );
45	
